detector_raw:
{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "What is the objective of this packing plan — for example, minimize the number of containers used, maximize the total weight of goods shipped, or something else?"
  ],
  "rationale": "The response contains a single clarification question asking for the specific objective of the packing plan, presented as a choice among examples."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Do all available goods have to be shipped (i.e., every unit of A, B, C, D, E must be packed into some container), or is it acceptable to leave some units unshipped?"
  ],
  "rationale": "The response asks a single clarification question regarding whether all goods must be shipped or if some can be left unshipped."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Is that intended (i.e., the plan must fit all goods into at most 7 containers), or should the 12-unit D minimum apply only to containers that actually contain D?"
  ],
  "rationale": "The response presents a single clarification question asking the user to choose between two interpretations of the constraint, which constitutes one semantically independent request."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Is that correct?"
  ],
  "rationale": "The response contains a single clarification question asking the user to confirm the assistant's interpretation of the constraints."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "The rule says a container with any type A must also contain at least one type C — is that the only A-related rule, i.e., there is no minimum number of A per container and no requirement that every container contain A?"
  ],
  "rationale": "The response asks a single compound clarification question seeking confirmation that the stated rule is the only constraint regarding type A, encompassing the absence of other specific A-related requirements."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Are the unit counts of each goods type in each container required to be whole numbers (you can't split a unit of goods across containers)?"
  ],
  "rationale": "The response contains a single clarification question asking whether unit counts must be integers."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Is the number of containers available unlimited (i.e., we can use as many containers as needed, subject to the 18–60 ton and 12-unit-D constraints), or is there a fixed fleet size we must work within?"
  ],
  "rationale": "The response asks a single clarification question regarding whether the container fleet size is unlimited or fixed."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "For the 18-ton minimum per used container, is 18 tons a strict lower bound that must be met exactly or at least (i.e., a container can be loaded with 18.5 tons, but not 17.9 tons)?"
  ],
  "rationale": "The response contains a single clarification question asking for the specific interpretation of the 18-ton minimum constraint (strict equality vs. lower bound)."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Is the 60-ton maximum per container a hard upper bound that must not be exceeded (i.e., a container can hold exactly 60 tons but not 60.5 tons)?"
  ],
  "rationale": "The response contains a single clarification question asking for confirmation of a specific constraint boundary."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Is there any limit on how many units of a single goods type can go into one container (e.g., a container could hold all 120 units of A), or is the only per-container restriction the 18–60 ton weight range and the 12-unit D minimum?"
  ],
  "rationale": "The response asks a single clarification question regarding per-container unit limits versus weight and minimum unit restrictions."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Is there any requirement that the goods be packed in a specific order or that containers be distinguishable (e.g., container 1, 2, 3...), or are containers interchangeable and only the total count matters?"
  ],
  "rationale": "The response asks a single clarification question regarding whether containers are distinguishable/ordered or interchangeable, which constitutes one independent semantic query."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Is there any other business rule or constraint I haven't asked about that I should know about before I build the model?"
  ],
  "rationale": "The response contains a single clarification question asking if there are any remaining business rules or constraints."
}
